using System;using System.Collections.Generic;using System.Linq;using System.Runtime.InteropServices;using System.Reflection;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Text;
namespace Citograph.Word {
 [ComVisible(true),Guid("B2C1FAE2-9F7B-4DB6-AAC2-AB6465C872F9"),ProgId("Citograph.WordAddin"),ClassInterface(ClassInterfaceType.AutoDispatch)]
 public class Addin:IDTExtensibility2,IRibbonExtensibility {
  private dynamic application,ribbon;private BridgeClient bridge=new BridgeClient();private DocumentController controller;private List<StyleInfo> styles=Data.StandardStyles();private Dictionary<string,object> pictures=new Dictionary<string,object>();
  public void OnConnection(object app,int mode,object instance,ref Array custom){application=app;controller=new DocumentController(app,bridge);dynamic addin=instance;addin.Object=this;Log("Connected to Word "+Convert.ToString(application.Version));}
  public void OnDisconnection(int mode,ref Array custom){application=null;ribbon=null;controller=null;}
  public void OnAddInsUpdate(ref Array custom){}public void OnStartupComplete(ref Array custom){}public void OnBeginShutdown(ref Array custom){}
  public string GetCustomUI(string id){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Citograph.Ribbon.xml"))using(var reader=new StreamReader(stream))return reader.ReadToEnd();}
  public void RibbonLoaded(object ui){ribbon=ui;Log("Ribbon loaded");}
  public object LoadImage(string id){object picture;if(pictures.TryGetValue(id,out picture))return picture;var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Citograph.Icons."+id+".png");if(stream==null)return null;using(stream){var bitmap=new Bitmap(stream);picture=PictureConverter.Convert(bitmap);pictures[id]=picture;return picture;}}
  public string Version(){return "1.4.3";}
  public void UseBridgeDescriptor(string file){bridge.descriptorOverride=Path.GetFullPath(file);}
  public void UseDocumentTarget(object document){controller=new DocumentController(application,bridge,document);}
  private WindowOwner Owner(){try{return new WindowOwner(new IntPtr((int)application.ActiveWindow.Hwnd));}catch{return null;}}
  private void Execute(Action action){Cursor old=Cursor.Current;try{Cursor.Current=Cursors.WaitCursor;action();if(ribbon!=null)ribbon.Invalidate();}catch(Exception e){Log(e.ToString());MessageBox.Show(Owner(),e.Message,"Citograph for Word",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{Cursor.Current=old;}}
  private LibraryResponse Available(){var data=bridge.Library();if(data.styles.Count>0)styles=data.styles;return data;}
  private void Pick(bool edit,bool traveling){var embedded=controller.TravelingReferences();LibraryResponse data;try{data=Available();}catch{if(!traveling&&embedded.Count==0)throw;data=new LibraryResponse{styles=styles};}FieldRecord field=edit?controller.SelectedCitation():null;using(var picker=new ReferencePicker(data,embedded,edit?"Edit citation":traveling?"Traveling library":"Find your next citation",field==null?null:field.payload)){if(picker.ShowDialog(Owner())==DialogResult.OK){if(edit)controller.Edit(field,picker.SelectedReferences,picker.Locator,picker.Prefix,picker.Suffix,picker.SuppressAuthor);else controller.Insert(picker.SelectedReferences,picker.Locator,picker.Prefix,picker.Suffix,picker.SuppressAuthor);}}}
  public void InsertClick(object control){Execute(()=>Pick(false,false));}public void EditClick(object control){Execute(()=>Pick(true,false));}public void TravelingClick(object control){Execute(()=>Pick(false,true));}
  public void UpdateClick(object control){Execute(()=>{string result=controller.Update();Status("Citations and bibliography updated.");});}
  public void BibliographyClick(object control){Execute(()=>{controller.Bibliography();Status("Bibliography updated at the end of the document.");});}
  public void RefreshClick(object control){Execute(()=>{var result=Data.Parse<Dictionary<string,object>>(controller.RefreshMetadata());Status(result["refreshed"]+" source snapshots refreshed.");});}
  public void OpenClick(object control){Execute(()=>bridge.OpenDesktop());}
  public void StyleMakerClick(object control){Execute(()=>bridge.OpenStyleStudio());}
  public void RefreshStylesClick(object control){Execute(()=>{Available();Status("Saved styles refreshed. Select a style to apply its latest version.");});}
  public string GetStyleTarget(){dynamic doc=controller.Document;string key=Convert.ToString(doc.FullName)+"|"+Convert.ToString(doc.ActiveWindow.Hwnd);string token;using(var hash=System.Security.Cryptography.SHA256.Create()){token=BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(key))).Replace("-","").ToLowerInvariant();}return Data.Serialize(new{token=token,window=Convert.ToInt64(doc.ActiveWindow.Hwnd),name=Convert.ToString(doc.Name),citations=controller.Fields().Count,readOnly=Convert.ToBoolean(doc.ReadOnly),style=controller.Library().style});}
  public string ApplyStyleToTarget(string id,string token){var target=Data.Parse<Dictionary<string,object>>(GetStyleTarget());if(Convert.ToString(target["token"])!=token)throw new InvalidOperationException("The active Word document changed. Inspect the target again before applying.");if(Convert.ToBoolean(target["readOnly"]))throw new InvalidOperationException("The Word document is read-only.");if(Convert.ToInt32(target["citations"])==0)throw new InvalidOperationException("Insert Citograph citations in this document first.");controller.SetStyle(id);if(ribbon!=null)ribbon.Invalidate();return Data.Serialize(new{name=target["name"],citations=target["citations"],style=id,applied=true});}
  public int StyleCount(object control){return styles.Count;}public string StyleId(object control,int index){return styles[index].id;}public string StyleLabel(object control,int index){return styles[index].name;}
  public int StyleIndex(object control){try{string id=controller.Library().style;int index=styles.FindIndex(s=>s.id==id);return index<0?0:index;}catch{return 0;}}
  public void StyleChanged(object control,string id,int index){Execute(()=>{controller.SetStyle(id);Status("Citation style changed to "+styles[index].name+".");});}
  public void ImportClick(object control){Execute(()=>{var result=Data.Parse<ImportResponse>(controller.ImportToDesktop());Status(result.added+" sources imported · "+result.skipped+" existing sources skipped.");});}
  public void ExportTravelingClick(object control){Execute(()=>Export(false));}public void ExportClick(object control){Execute(()=>{string html=controller.BibliographyMarkup();using(var dialog=new SaveFileDialog{Title="Export formatted bibliography",FileName="Citograph-bibliography",Filter="Formatted HTML (*.html)|*.html|Plain text (*.txt)|*.txt"}){if(dialog.ShowDialog(Owner())!=DialogResult.OK)return;string output=dialog.FilterIndex==1?"<!doctype html><html><head><meta charset=\"utf-8\"><title>Citograph bibliography</title><style>body{max-width:800px;margin:48px auto;font:16px/1.6 Georgia,serif}.csl-entry{margin:0 0 12px 24px;text-indent:-24px}.csl-left-margin{display:inline-block;min-width:24px}.csl-right-inline{display:inline}</style></head><body><h1>References</h1>"+RichText.SafeHtml(html)+"</body></html>":RichText.BibliographyText(html);File.WriteAllText(dialog.FileName,output,new UTF8Encoding(false));Status("Formatted bibliography exported.");}});}
  private void Export(bool bibliography){var refs=controller.TravelingReferences();using(var dialog=new SaveFileDialog{Title="Export document sources",FileName=bibliography?"Citograph-bibliography":"Citograph-traveling-library",Filter="CSL JSON (*.json)|*.json|RIS (*.ris)|*.ris|BibTeX (*.bib)|*.bib"}){if(dialog.ShowDialog(Owner())!=DialogResult.OK)return;string output;if(dialog.FilterIndex==1)output=bibliography?Data.Serialize(refs):controller.ExportTraveling();else if(dialog.FilterIndex==2)output=ExportData.Ris(refs);else output=ExportData.Bib(refs);File.WriteAllText(dialog.FileName,output,new UTF8Encoding(false));Status("Document sources exported.");}}
  public void AuditClick(object control){Execute(()=>{var report=Data.Parse<Dictionary<string,object>>(controller.Audit());var issues=((System.Collections.IEnumerable)report["issues"]).Cast<object>().Select(x=>Convert.ToString(x)).ToList();using(var form=UI.Report("Document check",report["citations"]+" citations · "+report["sources"]+" sources · "+report["bibliographies"]+" bibliographies",issues.Count==0?"All Citograph citation fields have valid data.\r\n\r\nUse Update Citations after moving, copying, or deleting citations.\r\n\r\nCore metadata checks evaluate field presence; they do not assess research quality.":string.Join("\r\n\r\n",issues)))form.ShowDialog(Owner());});}
  public void ManageClick(object control){Execute(()=>{var fields=controller.Fields();using(var form=new Form{Text="Citograph · Manage citations",Size=new Size(760,500),StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10),BackColor=Color.White}){var list=new ListBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,IntegralHeight=false};foreach(var f in fields)list.Items.Add((f.payload==null?"Damaged citation":RichText.Plain((string)f.field.Result.Text))+"  ·  "+(f.payload==null?"":f.payload.items.Count+" sources"));list.DoubleClick+=(s,e)=>{if(list.SelectedIndex>=0){fields[list.SelectedIndex].field.Result.Select();form.Close();}};var tip=new Label{Dock=DockStyle.Top,Height=60,Padding=new Padding(18),Text="Double-click a citation to jump to it in your document.",ForeColor=Color.FromArgb(146,133,164)};form.Controls.Add(list);form.Controls.Add(tip);form.ShowDialog(Owner());}});}
  public void ConvertClick(object control){Execute(()=>{if(MessageBox.Show(Owner(),"Convert Citograph citations and bibliographies in this document to ordinary text?\r\n\r\nTheir editable source links will be removed. Save a document copy first. Other Word fields are preserved.","Convert Citograph fields",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)==DialogResult.OK){controller.ConvertToText();Status("Citograph fields converted to plain text.");}});}
  public void HelpClick(object control){Execute(()=>{using(var form=UI.Report("Citograph for Word","Version 1.4.3 · Native Windows integration","INSERT CITATION\r\nSearch sources and select one or more. Use a page locator, prefix, suffix, or author suppression when needed.\r\n\r\nUPDATE CITATIONS\r\nRebuild numbering and bibliographies after moving or deleting citations.\r\n\r\nTRAVELING LIBRARY\r\nCitation fields carry CSL source metadata; the document stores its style and locale snapshot. Copied fields retain sources. The bibliography is an editable Citograph content control.\r\n\r\nREFRESH SOURCE METADATA\r\nBring the latest metadata from your desktop library into the document.\r\n\r\nCitograph 1.4.3 supplies the local citation processor. The add-in can start it in the background when required. No cloud service is used.\r\n\r\nWord documents retain their displayed citations without the add-in. PDF files and private research notes are not embedded."))form.ShowDialog(Owner());});}
  public string InsertCitationByIds(string ids,string locator,string prefix,string suffix,bool suppressAuthor){return controller.InsertByIds(ids,locator,prefix,suffix,suppressAuthor);}
  public string UpdateDocument(){return controller.Update();}public string InsertBibliography(){return controller.Bibliography();}public void SetCitationStyle(string id){controller.SetStyle(id);if(ribbon!=null)ribbon.Invalidate();}
  public string GetTravelingLibrary(){return controller.ExportTraveling();}public string CheckDocument(){return controller.Audit();}public string ImportDocumentLibrary(){return controller.ImportToDesktop();}public string RefreshSourceMetadata(){return controller.RefreshMetadata();}
  public string InspectEndNoteDocument(){return new EndNoteMigration(application,controller,bridge).Inspect();}
  public string MigrateEndNoteDocument(string output,string style,string token){return new EndNoteMigration(application,controller,bridge).Migrate(output,style,token);}
  public void MigrateEndNoteClick(object control){Execute(()=>{var report=Data.Parse<Dictionary<string,object>>(InspectEndNoteDocument());var available=Available();using(var review=new MigrationDialog(report,available.styles,controller.Library().style)){if(review.ShowDialog(Owner())!=DialogResult.OK)return;string extension=Convert.ToString(report["outputExtension"]);using(var save=new SaveFileDialog{Title="Create a migrated Citograph copy",FileName=Path.GetFileNameWithoutExtension(Convert.ToString(report["name"]))+"-Citograph"+extension,Filter=extension==".docm"?"Word document with macros (*.docm)|*.docm":"Word document (*.docx)|*.docx"}){if(save.ShowDialog(Owner())!=DialogResult.OK)return;var result=Data.Parse<Dictionary<string,object>>(MigrateEndNoteDocument(save.FileName,review.SelectedStyle,Convert.ToString(report["token"])));Status(result["citations"]+" citation groups migrated · "+result["added"]+" sources imported.");}}});}
  public void EditSelectedCitationByIds(string ids,string locator,string prefix,string suffix,bool suppressAuthor){var library=Available();var selected=new HashSet<string>(ids.Split(','));var refs=library.references.Where(r=>selected.Contains(Data.Text(r,"id"))).ToList();if(refs.Count!=selected.Count)throw new InvalidOperationException("Selected sources are unavailable.");controller.Edit(controller.SelectedCitation(),refs,locator,prefix,suffix,suppressAuthor);}
  public void ConvertDocumentToPlainText(){controller.ConvertToText();}
  private void Status(string message){try{application.StatusBar="Citograph · "+message;}catch{}}
  private static void Log(string message){try{string directory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Citograph","Word");Directory.CreateDirectory(directory);File.AppendAllText(Path.Combine(directory,"addin.log"),DateTime.Now.ToString("s")+" "+message+Environment.NewLine);}catch{}}
 }
 internal static class ExportData {
  public static string Ris(List<Dictionary<string,object>> refs){var lines=new List<string>();foreach(var r in refs){lines.Add("TY  - "+(Data.Text(r,"type")=="book"?"BOOK":"JOUR"));lines.Add("TI  - "+Data.Text(r,"title"));foreach(var name in Data.Authors(r).Split(';'))lines.Add("AU  - "+name.Trim());if(Data.Year(r).Length>0)lines.Add("PY  - "+Data.Year(r));foreach(var pair in new[]{new[]{"container-title","JO"},new[]{"DOI","DO"},new[]{"volume","VL"},new[]{"issue","IS"},new[]{"page","SP"},new[]{"URL","UR"}})if(Data.Text(r,pair[0]).Length>0)lines.Add(pair[1]+"  - "+Data.Text(r,pair[0]));lines.Add("ER  - ");lines.Add("");}return string.Join("\r\n",lines);}
  public static string Bib(List<Dictionary<string,object>> refs){var output=new StringBuilder();int i=0;foreach(var r in refs){output.Append("@"+(Data.Text(r,"type")=="book"?"book":"article")+"{citograph"+(++i)+",\r\n");var fields=new Dictionary<string,string>{{"title",Data.Text(r,"title")},{"author",Data.Authors(r).Replace("; "," and ")},{"year",Data.Year(r)},{"journal",Data.Text(r,"container-title")},{"doi",Data.Text(r,"DOI")},{"volume",Data.Text(r,"volume")},{"pages",Data.Text(r,"page")},{"publisher",Data.Text(r,"publisher")},{"url",Data.Text(r,"URL")}};output.Append(string.Join(",\r\n",fields.Where(p=>p.Value.Length>0).Select(p=>"  "+p.Key+" = {"+p.Value.Replace("{","\\{").Replace("}","\\}")+"}")));output.Append("\r\n}\r\n\r\n");}return output.ToString();}
 }
}
